/**
 * Synthetic test faces for the face-on-head spike (slice 6 of docs/research/photo-avatar-plan.md).
 * NOT a photo of anybody: the head v2 geometry of `@curtain/mannequin` (own hand-written curves),
 * painted per vertex with procedural features (sclera, iris, brows, lips, hair, blush, skin noise,
 * stubble) and lit by a warm side light, so the capture worker has a "photo" to find landmarks in
 * and to de-light. Three people, one per skin tone (Monk 2, 6, 9). The pictures are generated by
 * `synthface-renders.mjs` into `apps/web/e2e/fixtures/synthetic-faces/` and are this repository's
 * own work (no third-party asset, no model trained on faces).
 *
 * URL: `?person=a|b|c[&light=side|even][&yaw=deg]`.
 */
import * as THREE from 'three';
import { buildBody, buildMannequinMesh, FACE_LEVELS_V2 } from '@curtain/mannequin';

interface Person {
  family: 'female' | 'male';
  skin: string;
  hair: string;
  iris: string;
  lips: string;
  brow: string;
  /** Scale of the head across and up (identity cues the bake must normalise away). */
  sx: number;
  sy: number;
  freckles?: boolean;
  stubble?: boolean;
  hairline: number;
}

const PEOPLE: Record<string, Person> = {
  a: { family: 'female', skin: '#F3E7DB', hair: '#7A3E22', iris: '#5E7A8C', lips: '#C57E78', brow: '#6A3A24', sx: 1, sy: 1, freckles: true, hairline: 15.0 },
  b: { family: 'male', skin: '#A07E56', hair: '#2B1E16', iris: '#4B2E1C', lips: '#8C5948', brow: '#2B1E16', sx: 1.07, sy: 0.98, stubble: true, hairline: 15.6 },
  c: { family: 'female', skin: '#3A312A', hair: '#121010', iris: '#2B1A12', lips: '#53332D', brow: '#151111', sx: 0.97, sy: 1.04, hairline: 14.8 },
};

const params = new URLSearchParams(location.search);
const person = PEOPLE[params.get('person') ?? 'a'] ?? PEOPLE.a!;
const light = params.get('light') === 'even' ? 'even' : 'side';
const yawDeg = Number(params.get('yaw') ?? 0) || 0;

const smooth = (lo: number, hi: number, x: number): number => {
  const t = Math.min(1, Math.max(0, (x - lo) / (hi - lo)));
  return t * t * (3 - 2 * t);
};
/** Deterministic value noise in 3D (hash of the lattice, trilinear). */
function noise3(x: number, y: number, z: number): number {
  const h = (i: number, j: number, k: number): number => {
    let n = (i * 374761393 + j * 668265263 + k * 2147483647) | 0;
    n = (n ^ (n >>> 13)) * 1274126177;
    return ((n ^ (n >>> 16)) >>> 0) / 4294967295;
  };
  const xi = Math.floor(x), yi = Math.floor(y), zi = Math.floor(z);
  const fx = x - xi, fy = y - yi, fz = z - zi;
  const l = (a: number, b: number, t: number): number => a + (b - a) * (t * t * (3 - 2 * t));
  const c = (dz: number): number =>
    l(l(h(xi, yi, zi + dz), h(xi + 1, yi, zi + dz), fx), l(h(xi, yi + 1, zi + dz), h(xi + 1, yi + 1, zi + dz), fx), fy);
  return l(c(0), c(1), fz);
}

const col = (hex: string): THREE.Color => new THREE.Color(hex);

const m = buildBody({ family: person.family });
const mesh = buildMannequinMesh(m, { head: 'neutral-v2' });
const head = mesh.partNames.indexOf('head');
const { chinY, topY } = mesh.headLevels!;
const k = (topY - chinY) / 22;
const positions = Float32Array.from(mesh.positions);
// The person's own head proportions.
for (let i = 0; i < mesh.vertexPart.length; i++) {
  if (mesh.vertexPart[i] !== head) continue;
  const y = positions[3 * i + 1]!;
  const t = smooth(chinY - 1 * k, chinY + 2 * k, y);
  positions[3 * i] = positions[3 * i]! * (1 + (person.sx - 1) * t);
  positions[3 * i + 1] = chinY + (y - chinY) * (1 + (person.sy - 1) * t);
}
const g = new THREE.BufferGeometry();
g.setAttribute('position', new THREE.BufferAttribute(positions, 3));
g.setIndex(new THREE.BufferAttribute(mesh.indices, 1));
g.computeVertexNormals();
const nrm = g.getAttribute('normal') as THREE.BufferAttribute;

const skin = col(person.skin), hair = col(person.hair), iris = col(person.iris), lips = col(person.lips), brow = col(person.brow);
const sclera = col('#E6DED6'), pupil = col('#0B0908'), lash = col('#1A1210');
// Less colour in the blush on a deep skin (a strong red read as paint there).
const blush = skin.clone().lerp(col('#C0504A'), 0.18 * (0.35 + 0.65 * Math.min(1, skin.getHSL({ h: 0, s: 0, l: 0 }).l * 1.6)));
const colours = new Float32Array(positions.length);
const F = FACE_LEVELS_V2;
for (let i = 0; i < mesh.vertexPart.length; i++) {
  let c = skin.clone();
  if (mesh.vertexPart[i] === head) {
    // Unit coordinates of the undeformed head (the features follow the person's own proportions).
    const x = mesh.positions[3 * i]! / k, y = (mesh.positions[3 * i + 1]! - chinY) / k, z = mesh.positions[3 * i + 2]! / k;
    const nz = nrm.getZ(i);
    const front = smooth(0.25, 0.55, nz);
    // Skin texture: fine noise and a little redness on the cheeks and the nose.
    const n = noise3(x * 2.5, y * 2.5, z * 2.5) - 0.5;
    c.multiplyScalar(1 + 0.07 * n);
    const cheek = Math.exp(-(((Math.abs(x) - 3.7) / 1.6) ** 2 + ((y - 8.0) / 1.4) ** 2));
    const nose = Math.exp(-((x / 0.9) ** 2 + ((y - F.noseTip) / 0.9) ** 2));
    c.lerp(blush, front * Math.min(1, 0.9 * cheek + 0.5 * nose));
    if (person.freckles) {
      const f = noise3(x * 9, y * 9, 3.3);
      const zone = Math.exp(-((x / 3.6) ** 2 + ((y - 8.6) / 1.6) ** 2));
      if (f > 0.78) c.lerp(col('#B07A5A'), front * zone * 0.55);
    }
    if (person.stubble) {
      const jaw = smooth(7.2, 5.6, y) * smooth(-1.5, 1.0, y) * (1 - smooth(5.4, 6.4, Math.abs(x)));
      const upper = Math.exp(-((x / 2.4) ** 2 + ((y - 6.3) / 0.45) ** 2));
      const s = noise3(x * 14, y * 14, 1.7) > 0.45 ? 1 : 0.5;
      c.lerp(hair, Math.min(0.55, (jaw * 0.5 + upper * 0.45) * s) * smooth(0.0, 0.3, nz + 0.3));
    }
    // Lips.
    const ux = x / 2.3;
    if (front > 0 && Math.abs(ux) < 1) {
      const top = F.mouth + 0.62 * (1 - ux * ux) * (1 - 0.35 * Math.exp(-((x / 0.35) ** 2)));
      const bottom = F.mouth - 0.75 * (1 - (x / 2.1) ** 2);
      if (y < top && y > bottom) c.lerp(lips, front * smooth(0, 0.15, Math.min(top - y, y - bottom)));
      if (Math.abs(y - F.mouth) < 0.09) c.lerp(col('#2A1612'), front * 0.7 * (1 - ux * ux));
    }
    // Brows.
    for (const side of [-1, 1]) {
      const bx = x * side;
      if (bx > 0.9 && bx < 4.9 && front > 0) {
        const t = (bx - 1.0) / 3.9;
        const cy = F.brow + 0.25 + 0.45 * Math.sin(Math.PI * Math.min(1, t * 1.25)) - 0.25 * t;
        const half = 0.3 * (1 - 0.55 * t);
        const d = Math.abs(y - cy);
        if (d < half) c.lerp(brow, front * 0.92 * smooth(half, half * 0.5, d) * (noise3(x * 16, y * 6, 2) > 0.3 ? 1 : 0.7));
      }
      // Eyes.
      const ex = x - side * F.eyeX, ey = y - F.eyes;
      const r = Math.hypot(ex / 1.35, ey / (ey > 0 ? 0.6 : 0.45));
      if (front > 0 && r < 1) {
        c = sclera.clone().lerp(skin, smooth(0.8, 1, r));
        const ri = Math.hypot(ex - side * 0.05, ey + 0.02);
        if (ri < 0.6) c.copy(iris.clone().multiplyScalar(0.75 + 0.45 * smooth(0.6, 0.2, ri)));
        if (ri < 0.25) c.copy(pupil);
        if (ri > 0.52 && ri < 0.6) c.multiplyScalar(0.6);
      }
      if (front > 0 && ey > 0 && r > 0.92 && r < 1.22) c.lerp(lash, front * smooth(1.22, 1.0, r));
    }
    // Hair: above a hairline that drops from the forehead to the temples and the nape.
    const back = smooth(0.2, -0.6, nz);
    const hl = person.hairline - 2.6 * smooth(0.95, 0.15, nz) * (1 - back) - 7 * back;
    const fringe = noise3(x * 4, 0.5, z * 4) * 0.5;
    const ear = Math.abs(x) > 6.2 && y > 6.5 && y < 12.5 && Math.abs(nz) < 0.5 && z > -4;
    if (y > hl - fringe && !ear) {
      const strand = 0.8 + 0.4 * noise3(x * 6, y * 1.2, z * 6);
      c = hair.clone().multiplyScalar(strand);
    }
  }
  colours.set([c.r, c.g, c.b], 3 * i);
}
// THREE.Color from a hex is already linear (colour management), as three reads vertex colours.
g.setAttribute('color', new THREE.BufferAttribute(colours, 3));

const canvas = document.getElementById('stage') as HTMLCanvasElement;
const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, preserveDrawingBuffer: true });
renderer.setPixelRatio(1);
renderer.setSize(canvas.clientWidth, canvas.clientHeight, false);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.05;
const scene = new THREE.Scene();
scene.background = new THREE.Color('#D9DDE2');
const body = new THREE.Mesh(g, new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.62, metalness: 0 }));
body.rotation.y = (yawDeg * Math.PI) / 180;
scene.add(body);
if (light === 'side') {
  // A warm lamp from the upper left of the picture, a cool window fill from the right: the de-light step must flatten it.
  const key = new THREE.DirectionalLight('#FFE0BD', 3.0);
  key.position.set(-60, 40, 50);
  const fill = new THREE.DirectionalLight('#CFE0FF', 0.6);
  fill.position.set(70, 10, 40);
  scene.add(key, fill, new THREE.HemisphereLight('#FFFFFF', '#8A7F76', 0.9));
} else {
  const key = new THREE.DirectionalLight('#FFFFFF', 1.6);
  key.position.set(0, 20, 80);
  scene.add(key, new THREE.HemisphereLight('#FFFFFF', '#9A9A9A', 1.6));
}
const camera = new THREE.PerspectiveCamera(24, canvas.clientWidth / canvas.clientHeight, 1, 1000);
const eyeY = chinY + F.eyes * k * person.sy;
camera.position.set(0, eyeY - 1.5, 70);
camera.lookAt(0, eyeY - 5, 0);
renderer.render(scene, camera);
document.documentElement.dataset.ready = '1';
